  const name = r.pick(female ? nation.female : nation.male);
  const surname = r.pick(nation.surnames);
  const careerRec = opts.career
    ? CAREERS.find((c) => c.name === opts.career) ?? r.pick(CAREERS)
    : r.pick(CAREERS);
