/**
 * WHERE SHE STANDS, AND WHO IS DECIDING.
 *
 * The ladder with every gate visible, including the ones she has not cleared — because "you cannot
 * marry her yet" is not useful and "78% of her obedience is fear and this rung allows 22%" is the
 * whole game. The wall is the content.
 */
import { useState } from "react";
import { Heart, Loader2 } from "lucide-react";
import { useGame } from "../lib/game";
import { useHand } from "../lib/hand";
import { Button, Card, Chip, Meter, Money, Section, cx } from "../lib/ui";
import { LADDER, RUNGS, RUNG_BY_ID, RITES, ascend, nextRung, renounce, romanceOf, rungIndex, herReach } from "../engine/romance";
import { read } from "../engine/obedience";
import { generateAsk, voiceAsk } from "../engine/asks";
import { AskList } from "./AskCard";
import { runTurn } from "../engine/turn";
import { modelsAvailable } from "../config";
import { MannerCard, StandingOrders } from "./StandingOrders";
import { FREE_HOW, freeHer, freeLine, type FreeHow } from "../engine/freed";
import { KILL_HOW, killHer, type KillHow } from "../engine/execute";
import RoomCard from "./RoomCard";
import { governorshipOf, lockUp } from "../engine/governor";
import { speakToGovernor } from "../engine/talk";
import Talk from "./Talk";
import MarriageCard from "./MarriageCard";

export default function HerPanel({ id }: { id: string }) {
  const { save } = useGame();
  const mutate = useHand("people");
  const [busy, setBusy] = useState(false);
  const [rite, setRite] = useState<string | null>(null);
  const [quiet, setQuiet] = useState(false);
  const p = save.people[id];
  if (!p) return null;

  const rom = romanceOf(p);
  const r = read(p, save.memory[id]);
  const next = nextRung(save, p);
  const idx = rungIndex(rom.standing);
  const reach = herReach(p);
  const ask = save.asks?.find((a) => a.person === id) ?? null;

  async function climb() {
    if (!next?.ready) return;
    setBusy(true);
    let seed: string | undefined;
    mutate((s) => {
      const res = ascend(s, s.people[id]);
      seed = res.seed;
      for (const l of res.lines) s.notifications.push({ id: `n-rite-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`, week: s.arcology.week, text: l.text, kind: l.tone === "bad" ? "danger" : l.tone === "good" ? "good" : "info", person: id, seen: false });
    });
    // The rite is played as a scene when there is a narrator to play it.
    if (seed && modelsAvailable()) {
      await runTurn(save, seed, "story");
      mutate(() => {});
    }
    setRite(seed ?? null);
    setBusy(false);
  }

  return (
    <div className="space-y-4">
      {p.governs && governorshipOf(save, p.governs) ? (() => { const g = governorshipOf(save, p.governs!)!; return (
        <Card>
          <div className="text-[14px] mb-1">She governs {g.name} for you</div>
          <div className="text-[12px] dim mb-2">since week {g.since} · prosperity {Math.round(g.prosperity)} · order {Math.round(g.order)}</div>
          <Talk who={p.name} log={g.talk} send={(t) => speakToGovernor(save, g.place, t)} ideas={["How's my city?", "Tell me what you've done there.", "Come home for a week."]} />
        </Card>
      ); })() : null}
      <StandingOrders person={id} />
      <MannerCard person={id} />
      {p.governs ? null : <RoomCard id={id} />}
      {p.status === "owned" && !p.governs ? (
        p.assignment === "be confined in the cellblock"
          ? <Button size="sm" kind="ghost" onClick={() => mutate((s) => { const q = s.people[id]; q.facility = undefined; for (const f of Object.values(s.arcology.facilities)) f.workers = f.workers.filter((w) => w !== id); q.assignment = "rest"; })}>Let her out of the cell</Button>
          : <Button size="sm" kind="danger" onClick={() => mutate((s) => { lockUp(s, s.people[id], "locked in a cell"); })}>Lock her up</Button>
      ) : null}
      <Card>
        <div className="flex items-center gap-2 mb-3">
          <Heart size={14} className="acc" />
          <span className="text-[14px]">{RUNG_BY_ID[rom.standing].name}</span>
          <span className="text-[11px] dim">since week {rom.since_week}</span>
          {rom.exclusive ? <Chip tone="good">the only one</Chip> : null}
        </div>
        <p className="font-prose text-[14px] mid">{RUNG_BY_ID[rom.standing].what}</p>

        <div className="mt-4">
          <Meter value={rom.dominion} range={[-100, 100]} label="who is deciding — you ← → her" />
          <div className="text-[11px] dim mt-1">
            {rom.dominion <= -60 ? "You decide everything and she knows it."
              : rom.dominion < 0 ? "She has opinions. She mostly keeps them to herself."
              : rom.dominion < 40 ? "She says things now, and sometimes you do them."
              : rom.dominion < 70 ? "She moves people around the household and tells you afterwards."
              : rom.dominion < 85 ? "She runs most of it now and tells you what she did."
              : "She decides. You find out after."}
          </div>
          <div className="flex flex-wrap gap-1.5 mt-2">
            <Chip on={reach.assignments}>assignments</Chip>
            <Chip on={reach.purchases}>spending</Chip>
            <Chip on={reach.policy}>doctrine</Chip>
            <Chip on={reach.everything}>the books</Chip>
          </div>
          <div className="text-[11px] dim mt-2">You've given her what she asked for {rom.granted} time{rom.granted === 1 ? "" : "s"} and said no {rom.refused} time{rom.refused === 1 ? "" : "s"}.</div>
        </div>
      </Card>

      <MarriageCard id={id} />

      <AskList asks={(save.asks ?? []).filter((a) => a.person === id)} />
      {ask ? null : (
        <Button size="sm" kind="ghost" disabled={busy} onClick={async () => {
          setBusy(true);
          let a: ReturnType<typeof generateAsk> = null;
          mutate((s) => { a = generateAsk(s, s.people[id]); });
          const got = a as ReturnType<typeof generateAsk>;
          if (got) {
            got.text = await voiceAsk(save, got);
            mutate((s) => { s.asks = [...(s.asks ?? []).filter((x) => x.person !== id), got]; });
          } else setQuiet(true);
          setBusy(false);
        }}>
          {busy ? <Loader2 size={13} className="animate-spin" /> : "ask her what she wants"}
        </Button>
      )}
      {quiet && !ask ? <p className="text-[12.5px] dim">She doesn't ask for anything. {read(p, save.memory[id]).trust < 10 ? "She doesn't trust you enough to." : "She doesn't think you'd give her anything she wants right now."}</p> : null}

      <Section title="The ladder">
        <div className="space-y-2">
          {RUNGS.map((rung, i) => {
            const here = i === idx;
            const done = i < idx;
            const isNext = i === idx + 1;
            return (
              <div key={rung.id} className={cx("card-2 p-3", here && "border-l-2", !done && !here && !isNext && "opacity-45")}
                style={here ? { borderLeftColor: "var(--accent)" } : undefined}>
                <div className="flex items-baseline gap-2">
                  <span className={cx("text-[13px]", done && "dim")}>{rung.name}</span>
                  {done ? <Chip tone="good">done</Chip> : here ? <Chip on>here</Chip> : null}
                  {rung.rite && !done ? <span className="ml-auto text-[11px] dim">{RITES[rung.rite]?.cash ? <Money n={-RITES[rung.rite].cash} /> : "no cost"}</span> : null}
                </div>
                <div className="text-[12px] dim mt-0.5">{rung.what}</div>
                {isNext && next ? (
                  <div className="mt-2.5">
                    {next.ready ? (
                      <Button kind="primary" size="sm" disabled={busy} onClick={climb}>
                        {busy ? <Loader2 size={13} className="animate-spin" /> : RITES[rung.rite ?? ""]?.name ?? "go up"}
                      </Button>
                    ) : (
                      <ul className="text-[11.5px] space-y-1">
                        {next.blocked.map((b, j) => <li key={j} className="flex gap-2"><span className="bad">·</span><span className="mid">{b}</span></li>)}
                      </ul>
                    )}
                  </div>
                ) : null}
              </div>
            );
          })}
        </div>
      </Section>

      {rite ? (
        <Card>
          <div className="text-[11px] uppercase tracking-wider dim mb-1.5">it happened</div>
          <p className="font-prose text-[15px]">{rite}</p>
          <div className="text-[11.5px] dim mt-2">It's in the scene log.</div>
        </Card>
      ) : null}

      {idx > 0 ? (
        <Button kind="danger" size="sm" onClick={() => {
          const why = prompt(`Take it back from ${p.name}. Why?`, "you changed your mind");
          if (!why) return;
          mutate((s) => {
            for (const l of renounce(s, s.people[id], why)) {
              s.notifications.push({ id: `n-ren-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`, week: s.arcology.week, text: l.text, kind: "danger", person: id, seen: false });
            }
          });
        }}>take it back</Button>
      ) : null}

      <LetHerGo id={id} />
      <KillHer id={id} />

      <Card className="text-[11.5px] dim">
        {r.fragility > 0.5 ? "She obeys you more out of fear than love." : "She obeys you more out of love than fear."} To court her it has to be mostly love, and to marry her, almost all of it.
      </Card>
    </div>
  );
}

/** Free her, and she goes on living in your city. Or, once she has, where she is now. */
function LetHerGo({ id }: { id: string }) {
  const { save } = useGame();
  const mutate = useHand("people");
  const [open, setOpen] = useState(false);
  const [said, setSaid] = useState("");
  const p = save.people[id];
  if (!p) return null;
  if (p.status === "free" && p.free_life) return <Card className="text-[13px]"><div className="text-[11px] uppercase tracking-wider dim mb-1">Her life now</div>{freeLine(save, p)}</Card>;
  if (p.status !== "owned" && p.status !== "indentured") return said ? <Card className="text-[13px] acc">{said}</Card> : null;
  return (
    <Card>
      <div className="flex items-center gap-2">
        <div className="text-[11px] uppercase tracking-wider dim flex-1">Let her go</div>
        <Button size="sm" kind="ghost" onClick={() => setOpen((v) => !v)}>{open ? "not now" : "free her"}</Button>
      </div>
      {open ? (
        <div className="mt-2 space-y-1.5">
          <div className="text-[12px] dim">She'll live in your city afterwards, off your roster. She takes work in one of your districts, and you'll run into her.</div>
          {(Object.keys(FREE_HOW) as FreeHow[]).map((how) => {
            const cost = FREE_HOW[how].cost(save);
            return (
              <button key={how} className="choice" disabled={save.arcology.cash < cost} onClick={() => { let r = { ok: false, line: "" }; mutate((s) => { r = freeHer(s, id, how); }); setSaid(r.line); setOpen(false); }}>
                <span className="block text-[14px] leading-snug">{FREE_HOW[how].label}{cost ? ` · ¤${cost.toLocaleString()}` : ""}</span>
                <span className="block text-[11.5px] dim mt-0.5">{FREE_HOW[how].note}</span>
              </button>
            );
          })}
        </div>
      ) : null}
    </Card>
  );
}

/** Kill her. Two steps, so a stray tap doesn't do it. */
function KillHer({ id }: { id: string }) {
  const { save } = useGame();
  const mutate = useHand("people");
  const [open, setOpen] = useState(false);
  const [said, setSaid] = useState("");
  const p = save.people[id];
  if (!p) return null;
  if (p.status === "dead") return said ? <Card className="text-[13px] bad">{said}</Card> : null;
  if (p.status !== "owned" && p.status !== "indentured") return null;
  return (
    <Card>
      <div className="flex items-center gap-2">
        <div className="text-[11px] uppercase tracking-wider dim flex-1">Kill her</div>
        <Button size="sm" kind={open ? "ghost" : "danger"} onClick={() => setOpen((v) => !v)}>{open ? "not now" : "kill her"}</Button>
      </div>
      {open ? (
        <div className="mt-2 space-y-1.5">
          <div className="text-[12px] dim">She's dead and off your roster. Everyone in the household feels it.</div>
          {(Object.keys(KILL_HOW) as KillHow[]).map((how) => (
            <button key={how} className="choice" onClick={() => { let r = { ok: false, line: "" }; mutate((s) => { r = killHer(s, id, how); }); setSaid(r.line); setOpen(false); }}>
              <span className="block text-[14px] leading-snug">{KILL_HOW[how].label}</span>
              <span className="block text-[11.5px] dim mt-0.5">{KILL_HOW[how].note}</span>
            </button>
          ))}
        </div>
      ) : null}
    </Card>
  );
}
