import { runOrders } from "./rules";
import { selectEvents } from "./events";
import { selectClassics } from "./classics";
import { rollMarkets, recruitResult } from "./market";
import { rng } from "./rng";
import { runHeadGirl, runManager, type ManagerEffect } from "./managers";
import { tickPolicies } from "./policies";
import { heldDown, tickSecurity, unrest, unrestLine } from "./security";
import { GARMENT_BY_NAME } from "../data/wardrobe";
import { refreshPlayer, practise, skill, tickTraining } from "./player";
import { tickAllowance } from "./allowance";
import { tickRomance, keeperRunsTheWeek, theKeeper, romanceOf, inHousehold } from "./romance";
import { collectAsks } from "./asks";
import { tickReversal } from "./reversal";
import { tickStory } from "./story";
import { tickEndowment } from "./endowment";
import { tickFew } from "./fewslaves";
import { tickMarriage } from "./marriage";
import { ageMoments } from "./moments";
import { tickDeeds } from "./deeds";
import { tickCulture } from "./culture";
import { tickCourt } from "./court";
import { tickReign } from "./reign";
import { tickCampaigns } from "./civic";
// Trouble around each kind of district you own (engine/districtlife); registered on import.
import "./districtlife";
import { tickWorld } from "./world";
import { tickGlobe } from "./globe";
import { tickWorks } from "./works";
import { tickGenome, menialResistance } from "./genome";
import { tickMenials } from "./menials";
import { pruneFaces, settleFaces, syncStoryCast } from "./faces";
import { purgeBanned } from "./bans";
import { oneEach } from "./pending";
import { tickSagas } from "./saga";
import { modelsAvailable } from "../config";
import { cityThisWeek } from "./citylife";
import "./systemevents";
import { tickRun } from "./run";
import { tickCity, cityYield } from "./city";
import { tickThreads } from "./threads";
