import { canSire } from "./you";
import { comfort, tickRoom } from "./rooms";
import { tickGovernors } from "./governor";

// The woman who holds your collar is free, but she still lives here: her body, her mind and her memory keep going.
const alive = (s: SaveState): Person[] => Object.values(s.people).filter((p) => inHousehold(s, p));

export function endWeek(s: SaveState): WeekReport {
  const week = s.arcology.week;
  const led = new Ledger();
  const lines: ReportLine[] = [];
  const problems: string[] = [];
  const cashStart = s.arcology.cash;
  const repStart = s.arcology.rep;
  const r = rng(`week:${week}`);

  const push = (text: string, tone: ReportLine["tone"] = "neutral", weight = 5, person?: string, facility?: string) =>
    lines.push({ text, tone, weight, person, facility });

  /* ── 1. standing orders ─────────────────────────────────────────────────────────────────── */
  const ruleRuns = runOrders(s, false);
  for (const run of ruleRuns) {
    const p = s.people[run.person];
    const order = s.orders.find((o) => o.id === run.rule);
    if (p && order) push(`${order.name}: ${p.name} — ${run.changes.join("; ")}`, "neutral", 3, p.id);
  }

  /* ── 1b. the people who run things ──────────────────────────────────────────────────────── */
  // Managers are resolved BEFORE the work, because what they do is change what the work is. Their
  // own week is worked in the loop below like anybody else's.
  const managed = new Map<string, ManagerEffect>();
  for (const fac of Object.values(s.arcology.facilities)) {
    // What a busy facility's upgrades do for the place as a whole: the club's lights, the drones.
    const whole = upgradeAdds(fac.upgrades, FACILITY_BY_ID[fac.kind]);
    if (fac.level && fac.workers.length) {
      if (whole.rep) s.arcology.rep += whole.rep;
      if (whole.security) s.arcology.security = clamp(s.arcology.security + whole.security, 0, 100);
    }
    if (!fac.level || !fac.manager) continue;
    const eff = runManager(s, fac.id);
    managed.set(fac.id, eff);
    lines.push(...eff.lines);
  }
  lines.push(...runHeadGirl(s));

  /* ── 2. the work ────────────────────────────────────────────────────────────────────────── */
  const town = cityYield(s);
  const schooling = town.schooling;
  const dead: Person[] = [];
  const housed = alive(s);
  const meanComfort = housed.length ? housed.reduce((n, p) => n + comfort(p), 0) / housed.length : 0;
  for (const p of alive(s)) {
    p.economics.weeks_owned++;
    const fac = p.facility ? s.arcology.facilities[p.facility] : undefined;
    const facDef = fac ? FACILITY_BY_ID[fac.kind] : undefined;
    const asgDef = ASSIGNMENT_BY_ID[p.assignment];
    const base = facDef?.psyche ?? asgDef?.psyche ?? { relaxation: 0, wear: 0, health: 0, energy: 20 };
    // What the facility's upgrades add to the work, on top of the work itself (data/facilities).
    const adds = upgradeAdds(fac?.upgrades, facDef);
    const load = { relaxation: base.relaxation + adds.relaxation, wear: base.wear + adds.wear, health: base.health + adds.health, energy: base.energy + adds.energy };
    if (adds.fear) p.bond.fear = clamp(p.bond.fear + adds.fear, 0, 100);
    if (adds.education) p.persona.education = clamp(p.persona.education + adds.education, 0, 100);

    const mgr = p.facility ? managed.get(p.facility) : undefined;
    const managedByThem = mgr && fac?.manager !== p.id;

    // MONEY
    for (const l of tickIdol(s, p)) push(l, "good", 5, p.id);
    for (const l of tickFlesh(s, p)) push(l, "neutral", 6, p.id);
    const money = weeklyMoney(s, p);
    if (managedByThem && mgr) money.income = Math.round(money.income * mgr.income);
    // What she's good at, when her work uses it (engine/character).
    const knack = talentFits(p);
    if (knack && money.income > 0) money.income = Math.round(money.income * 1.15);
    // Her quirk suits the work, or her flaw gets in its way (engine/sexlife).
    const suits = jobFit(s, p);
    if (money.income > 0 && suits.mult !== 1) money.income = Math.round(money.income * suits.mult);
    // And her work feeds what she needs, or doesn't.
    const need = weeklyDesires(s, p);
    if (need) push(need, need.includes("happier") ? "good" : "bad", 6, p.id);
    // And whether she did what she was told this week (engine/compliance).
    const misdeed = misbehave(s, p);
    if (misdeed) {
      money.income = Math.round(money.income * misdeed.cut);
      push(`${p.name} ${misdeed.what}.`, "bad", 7, p.id);
    }
    if (money.income) led.earn("slaves", `${p.name} — ${money.note || p.assignment}`, money.income, p.id);
    led.spend("upkeep", `${p.name}`, money.upkeep, p.id);
    if (money.rep) led.entry("standing", `${p.name}`, 0, money.rep, p.id);
    p.economics.income_last_week = money.income;
    p.economics.income_lifetime += money.income;
    p.economics.upkeep_last_week = money.upkeep;
    p.economics.upkeep_lifetime += money.upkeep;
    p.economics.customers_last_week = money.customers;

    // WORK ON THE NERVOUS SYSTEM. This is where a facility stops being a multiplier and starts
    // being a place: the shove lands, the resting point takes the wear, and the emotion the work
    // produced gets a name that the narrator will use later.
    tickWeek(p.psyche);
    // What she is wearing, every day, all week. Small and relentless — the way clothing actually is.
    let worn = 0;
    for (const item of [p.clothes, p.collar, p.shoes]) worn += GARMENT_BY_NAME[item]?.relaxation ?? 0;
    // The city's therapy offices take the broken ones in hand (data/districts).
    const mended = p.psyche.state !== "intact" ? adds.mending + Math.min(1.2, town.mending * 0.3) : 0;
    const felt = shove(p.psyche, load.relaxation * (1 + (p.health.energy < 25 ? 0.4 : 0)) + worn + (managedByThem && mgr ? mgr.care : 0) + mended);
    // And restaurant row feeds them: a decent meal every day is a little hope.
    if (town.fare) p.bond.hope = clamp(p.bond.hope + Math.min(1, town.fare * 0.15), 0, 100);
    if (load.wear < -0.8) p.psyche.braced_run += 2;
    if (load.wear > 0.8) p.psyche.settled_run += 2;

    if (facDef?.id === "arcade" && r.chance(0.5)) addState(p.psyche, "dread of the booth", week);
    if (facDef?.id === "cellblock") addState(p.psyche, "fear of the wardeness", week);
    if (facDef?.id === "spa" && p.psyche.relaxation > 2) addState(p.psyche, "relief", week);

    const emo = tickEmotions(p.psyche, week);
    if (emo.liberated.length) push(`${p.name} has come to terms with ${emo.liberated[0]}.`, "good", 4, p.id);
    if (emo.fed) push(`${p.name} keeps dwelling on ${emo.fed}, and it's wearing her down.`, "bad", 4, p.id);
    const dis = tickDischarge(p.psyche);
    if (dis.fired) push(`${p.name} had a breakdown this week, and came out the other side${dis.released ? `; she's no longer ${dis.released}` : ""}.`, "good", 7, p.id);

    // TRAINING
    const trains = { ...(facDef?.trains ?? {}), ...(asgDef?.trains ?? {}) };
    const aptitude = 1 + ({ impaired: -0.5, slow: -0.25, average: 0, sharp: 0.25, brilliant: 0.5 }[p.persona.intelligence]);
    const willing = clamp(1 + read(p).devotion / 200, 0.4, 1.4);
    const teacher = (fac && facDef?.manager && fac.manager ? 1.7 : 1) * skill.slaving(s);
    for (const [skill, rate] of Object.entries(trains)) {
      const gain = (rate as number) * aptitude * willing * teacher * (managedByThem && mgr ? mgr.training : 1) * (1 + adds.training);
      const key = skill as keyof typeof p.skills;
      if (typeof p.skills[key] === "number") {
        const before = p.skills[key] as number;
        (p.skills[key] as number) = clamp(before + gain, 0, 100);
        if (Math.floor(before / 25) < Math.floor((p.skills[key] as number) / 25)) push(`${p.name}'s ${skill} skill has improved.`, "good", 3, p.id);
      }
    }
    // The academy is a district, and this is where it is felt: every level in the city makes every
    // woman in classes learn faster. A yield nobody can feel is a yield that should not exist.
    if (p.assignment === "classes" || fac?.kind === "schoolroom") {
      p.persona.education = clamp(p.persona.education + 2.5 * aptitude * (1 + schooling), 0, 100);
    }

    // MANAGEMENT SKILL, for whoever is running something
    if (fac && fac.manager === p.id && facDef?.manager) {
      const k = facDef.manager.skill;
      p.skills.management[k] = clamp((p.skills.management[k] ?? 0) + 3, 0, 100);
    }

    // HEALTH AND THE BODY
    const hw = tickHealth(s, p, { health: load.health + (managedByThem && mgr ? mgr.health : 0), energy: load.energy });
    for (const n of hw.notes) push(`${p.name}: ${n}.`, n.includes("healed") || n.includes("back on her feet") ? "good" : "bad", 5, p.id);
    if (hw.died) { dead.push(p); continue; }
    weeklyRelease(s, p);

    // SEX, AND WHAT COMES OF IT
    const exposure = sexualExposure(p, s);
    if (exposure > 0 && !p.womb.contraceptives) {
      const f = tryConception(s, p, null, exposure);
      if (f) push(`${p.name} is pregnant.`, "neutral", 6, p.id);
    }
    const preg = tickPregnancy(s, p);
    for (const n of preg.notes) push(`${p.name}: ${n}.`, "neutral", 5, p.id);
    for (const child of preg.born) {
      push(`${p.name} gave birth to ${child.name}.`, "good", 9, p.id);
      startRumor(s, `${p.name} had her baby`, { about: p.id, salience: 6, from: p.id });
    }
    for (const n of tickChild(s, p)) push(n, "neutral", 7, p.id);
    for (const n of tickAge(s, p)) push(n, "neutral", 3, p.id);

    // THE WEEK, AS SHE WILL REMEMBER IT
    const mem = s.memory[p.id];
    if (mem) {
      const charge = felt < -1.2 ? "sharp" : felt > 1 ? "warm" : "dull";
      const importance = Math.min(9, Math.round(Math.abs(felt) * 2.5 + (money.customers > 40 ? 2 : 0)));
      if (importance >= 3) {
        remember(mem, {
          content: weekMemory(p, facDef?.name ?? asgDef?.label ?? p.assignment, money),
          week, importance, charge, where: facDef?.name ?? "the penthouse",
        });
      }
      decayMemory(mem, week);
      if (week % 8 === 0) {
        const belief = reflect(mem, week, p.psyche.relaxation < -2);
        if (belief) push(`${p.name} has decided: "${belief}"`, "neutral", 6, p.id);
      }
    }

    // The bond ledger, and what the week did to it without anybody deciding.
    if (facDef?.id === "arcade" || facDef?.id === "cellblock") {
      applyTreatment(p, { kind: "cruelty", size: facDef.id === "arcade" ? 4 : 3, why: `a week in the ${facDef.name.toLowerCase()}` }, week);
    } else if (p.assignment === "be confined in the cellblock") {
      applyTreatment(p, { kind: "cruelty", size: 3, why: "a week locked in a storeroom" }, week);
      addState(p.psyche, "dread of the cell", week);
    } else if (facDef?.id === "spa" || facDef?.id === "master_suite") {
      applyTreatment(p, { kind: "kindness", size: 2, why: `a week in the ${facDef.name.toLowerCase()}` }, week);
    }
    // Where she sleeps, every night of it.
    const room = tickRoom(s, p, meanComfort);
    if (room.upkeep) led.spend("upkeep", `${p.name}'s room`, room.upkeep, p.id);
    if (room.line) push(room.line, "neutral", 4, p.id);
    // Her allowance, paid into her own purse, and some of it spent.
    const pay = tickAllowance(s, p);
    if (pay.paid) led.spend("allowance", `${p.name}'s allowance`, pay.paid, p.id);
    for (const l of pay.lines) push(l.text, l.tone, 4, p.id);
    tickBond(p, heldDown(s));
    lines.push(...tickRomance(s, p));
    refresh(p, mem);

    // Indenture runs down, and it is the one clock the player cannot quietly extend.
    if (p.status === "indentured" && p.indenture_weeks !== undefined) {
      p.indenture_weeks--;
      if (p.indenture_weeks <= 0) {
        p.status = "free";
        p.exit_week = week;
        p.exit_note = "indenture expired";
        push(`${p.name}'s indenture is over. She's a free citizen as of Monday.`, "warning", 9, p.id);
      }
    }
  }

  for (const p of dead) {
    p.status = "dead";
    p.exit_week = week;
    p.exit_note = "died";
    push(`${p.name} died.`, "bad", 10, p.id);
    startRumor(s, `${p.name} died in the ${p.facility ?? "penthouse"}`, { salience: 8, about: p.id });
    for (const other of alive(s)) {
      shove(other.psyche, -0.6, { hard: true });
      other.bond.fear = clamp(other.bond.fear + 6, 0, 100);
    }
  }

  /* ── 3. the household reacts to itself ──────────────────────────────────────────────────── */
  tickProximity(s);
  const pulled = coRegulate(s);
  const flips = pulled.filter((x) => Math.abs(x.pull) > 0.25).length;
  if (flips >= 3) push(`The mood of ${flips} of your slaves shifted together this week.`, "neutral", 4);
  // Seed from the week that just happened, then let it spread. Seeding after diffusion would
  // mean a new rumour is known by exactly one person for a week, which is not how a house works.
  gossip(s, week);
  diffuseRumors(s);
  for (const rum of s.rumors) {
    if (rum.week === week - 1 && rum.knowers.length > 3) push(`Everyone has heard the rumor: ${rum.content}.`, "neutral", 3);
  }

  // THREADS. Last of the household passes, because a detector has to read the week that just
  // happened rather than the one before it — and the trace it records is what next week's
  // detectors will read a trend out of.
  const threads = tickThreads(s);
  lines.push(...threads.lines);
  for (const t of threads.opened) {
    const def = THREAD_BY_KIND[t.kind];
    if (def) push(`${def.blurb}`, "warning", 10);
  }

  // Whoever is running this place, if it is not you.
  lines.push(...keeperRunsTheWeek(s).lines);

  /* ── 4. the arcology reacts to the household ────────────────────────────────────────────── */
  lines.push(...tickPolicies(s, led));

  const sec = tickSecurity(s);
  lines.push(...sec.lines);
  if (sec.cash) led.entry("security", "security losses", sec.cash);

  // THE CITY, first among the world passes: what it produces this week is what the arcology then
  // spends, so it has to settle before the ledger closes.
  const cityWeek = tickCity(s);
  lines.push(...cityWeek.lines);
  if (cityWeek.cash) led.entry("city", "districts and trade", cityWeek.cash);

  // The plot chain, which is a society pass of its own: it moves your standing with the trade, it
  // moves the arcology's adoption, and it is where the service fees come from once they are open.
  lines.push(...tickReversal(s));
  // What the city says about you, and what a small household does to the women in it.
  for (const l of tickEndowment(s)) push(l.text, l.tone, l.weight);
  for (const l of tickFew(s)) push(l.text, l.tone, l.weight, l.person);
  for (const l of tickMarriage(s)) push(l.text, l.tone, l.weight, l.person);
  for (const l of tickStory(s)) push(l.text, l.tone, l.weight);
  lines.push(...tickRun(s));

  const secr = secretaryRebate(s, led.lines.filter((l) => l.category === "upkeep").reduce((n, l) => n - l.cash, 0));
  if (secr.cash > 0 && secr.who) led.earn("savings", `${secr.who.name} caught overcharges in the accounts`, secr.cash, secr.who.id);

  const soc = tickSociety(s);
  led.entry("doctrine", "your citizens, on how you live", soc.cash, soc.rep);
  for (const l of soc.lines) push(l, "neutral", 6);
  const feet = tickPodolatry(s);
  if (feet.cash || feet.rep) led.entry("doctrine", "Podolatry: the washing and the tithe", feet.cash, feet.rep);
  for (const l of feet.lines) push(l, "neutral", 4);
  for (const l of tickCuckold(s)) push(l.text, "neutral", 6, l.person);

  // THE WORLD: weather, climate, the economy, the regions. Before the money is settled, because the
  // weather changes what the farms grew and what the power cost.
  lines.push(...tickWorld(s, led));
  // The public gardens take some of it back out of the air.
  if (s.world && town.clean) s.world.pollution = clamp(s.world.pollution - Math.min(4, town.clean * 0.6), 0, 100);
  for (const l of tickGlobe(s)) push(l, "good", 8);
  tickWorks(s, led);
  for (const l of tickGenome(s)) push(l, "neutral", 5);
  for (const l of tickMenials(s, led, menialResistance(s))) push(l, "warning", 5);
  syncStoryCast(s);
  for (const l of tickSagas(s, modelsAvailable())) push(l, "warning", 11);
  pruneFaces(s);
  // Whoever a scene filed this week under a second spelling, or as one of the player's own, is folded back.
  settleFaces(s);
  tickMarks(s);
  ageMoments(s);
  for (const e of tickDeeds(s)) push(e.text, "warning", 8, e.person);
  // The city's habits move with what it saw you do this week, and the court writes them down.
  // What they did with each other this week, and a dispute for you now and then.
  for (const l of tickHousehold(s)) push(l, "neutral", 4);
  const camp = tickCampaigns(s);
  if (camp.cash) led.entry("doctrine", "your campaigns", camp.cash);
  for (const l of camp.lines) push(l, "neutral", 4);
  for (const l of tickCulture(s)) push(l, "neutral", 7);
  for (const l of tickCourt(s)) push(l, "warning", 7);
  for (const l of lawPulseTagged(s)) push(l.line, "neutral", 6, undefined, `law:${l.law}`);
  // If she holds your collar, the week is hers: her orders, her household, her laws.
  for (const l of tickReign(s)) push(l.text, l.tone, l.weight, l.person);

  arcologyMoney(s, led);
  for (const l of tickCorp(s, led)) push(l, "bad", 8);
  for (const l of tickFCTV(s, led)) push(l, "neutral", 3);
  for (const l of tickBattles(s)) push(l, "bad", 12);
  for (const l of tickFreed(s)) push(l, "neutral", 4);
  for (const l of tickTraining(s)) push(l, "good", 6);
  const pow = tickPowers(s);
  led.entry("Empire", "Arsenal upkeep, tribute, pacts and sanctions", pow.cash);
  for (const l of pow.lines) push(l, "warning", 9);
  // The other powers' own week, and anything it brings to you. With a model, what's worth your
  // attention is decided after the week by engine/living's world desk.
  const reg = tickRegion(s, !(modelsAvailable() && !s.models.lean_mode));
  if (reg.cash) led.entry("Empire", "What the other powers sent or cost you", reg.cash);
  for (const l of reg.lines) push(l, "warning", 8);
  const gov = tickGovernors(s);
  if (gov.cash) led.entry("Empire", "Your soldiers in the cities your women run", gov.cash);
  for (const l of gov.lines) push(l.text, l.tone, 9, l.person);
  const wars = tickWars(s);
  led.entry("Empire", "The cost of war", wars.cash);
  for (const l of wars.lines) push(l, "warning", 11);

  const arc = s.arcology;
  const staff = alive(s).length;
  const publicWork = alive(s).filter((p) => p.assignment === "public servant" || p.assignment === "whore").length;
  arc.prosperity = clamp(arc.prosperity + clamp((led.cash / 3500) + publicWork * 0.4 - (arc.crime / 40), -6, 6), 5, 200);
  arc.crime = clamp(arc.crime + (arc.security < 30 ? 3 : -2) + (arc.prosperity < 40 ? 2 : -1), 0, 100);
  arc.population = Math.round(clamp(arc.population * (1 + (arc.prosperity - 60) / 4000), 200, 20000));
  arc.ownership = clamp(arc.ownership + (arc.cash > 60000 ? 0.4 : 0), 0, 100);

  /* ── 5. the world reacts to the arcology ────────────────────────────────────────────────── */
  for (const n of arc.neighbours) {
    n.prosperity = clamp(n.prosperity + r.normal(0, 2), 10, 200);
    n.attitude = clamp(n.attitude + (arc.prosperity > n.prosperity ? -1.2 : 0.6) + skill.diplomacy(s) * 1.2, -100, 100);
  }
  for (const proj of [...arc.projects]) {
    proj.weeks_left--;
    if (proj.weeks_left <= 0) {
      arc.projects = arc.projects.filter((x) => x.id !== proj.id);
      push(`${proj.title} is finished.`, "good", 8);
      applyProjectEffect(s, proj.on_complete);
    }
  }
  for (const loan of [...arc.loans]) {
    if (week >= loan.due_week) {
      const owed = Math.round(loan.principal * (1 + loan.apr / 4));
      if (arc.cash >= owed) { arc.cash -= owed; arc.loans = arc.loans.filter((l) => l !== loan); push(`Repaid the ${loan.lender}: ${owed}.`, "neutral", 6); }
      else { problems.push(`The ${loan.lender} wants ${owed}, and you can't pay.`); if (loan.lender === "shark") { arc.security = clamp(arc.security - 15, 0, 100); push(`The loan shark's thugs came to the residential level. Security is down fifteen.`, "bad", 10); } }
    }
  }

  const recruiter = alive(s).find((p) => p.assignment === "recruit girls");
  if (recruiter) {
    const found = recruitResult(s, recruiter);
    if (found) {
      s.market.offers["recruit"] = [found];
      push(`${recruiter.name} has recruited a new slave. She's waiting in reception.`, "good", 8, recruiter.id);
    }
  }

  /* ── 6. bookkeeping, and the shape of next week ─────────────────────────────────────────── */
  arc.cash += led.cash;
  arc.rep = Math.max(0, arc.rep + led.rep);
  arc.week++;
  // A new week starts somewhere new. Whatever room the last scene ended in, a week has gone by
  // since: Monday morning, the penthouse, whoever works there.
  s.scene = { ...s.scene, location: PLACE_BY_ID.penthouse.name, time: `Week ${arc.week}, Monday 09:00`,
    present: occupants(s, PLACE_BY_ID.penthouse).map((p) => p.id), present_prev: [], arrivals_pending: [], departures_pending: [] };

  s.market = rollMarkets(s);
  // What the household wants from you this week. Two, at most, and the ones with the most standing
  // to ask go first — a screen of twelve requests is a queue, and a queue is not a decision.
  // With a model writing the week, requests come out of engine/wants (only when she has reasons);
  // without one, the game's own two a week.
  const writer = modelsAvailable() && !s.models.lean_mode;
  s.asks = writer ? [] : collectAsks(s);
  for (const ask of s.asks) {
    const who = s.people[ask.person];
    if (who) push(`${who.name} wants something.`, "neutral", 7, who.id);
  }
  const fresh = [...selectEvents(s, { writer }), ...selectClassics(s)];
  // An event about someone who's gone (dead, sold) can't be about her any more.
  const here = (e: { person?: string }) => !e.person || ["owned", "indentured", "free"].includes(s.people[e.person]?.status ?? "");
  s.events = [...s.events.filter((e) => week - e.week < 2 && here(e)), ...fresh];
  // Nothing about a storyline the player ended makes it onto this week's table, and nobody has more
  // than one thing waiting (engine/pending).
  purgeBanned(s);
  oneEach(s);
  for (const e of fresh) {
    push(e.seed, e.severity === "major" ? "warning" : "neutral", 10, e.person);
  }

  if (arc.cash < 0) problems.push(`You are ${Math.abs(arc.cash)} in the red.`);
  if (arc.food.stores < 100 && arc.food.consumption > 0) problems.push(`Food stores are nearly out. The city eats ${arc.food.consumption.toLocaleString()} a week${s.menials?.owned ? ` (${(s.menials.owned * 2).toLocaleString()} of it your menials)` : ""}, and the shortfall is bought at ¤8 a unit. Automated farm decks or hydroponic towers (Arcology → Public works), or menials on the farms (each grows 14 and eats 2), fix it.`);
  const overworked = alive(s).filter((p) => p.health.energy < 12);
  if (overworked.length) problems.push(`${overworked.length} of your slaves are exhausted.`);
  const wornOut = alive(s).filter((p) => wear(p.psyche) > 0.7);
  if (wornOut.length) problems.push(`${wornOut.length} of your slaves have been stressed for so long it's permanently affected them.`);
  const u = unrest(s);
  if (u > 50) problems.push(unrestLine(s, u));

  // You get better at this by doing it: a week of running a household is a week of practice.
  practise(s, "slaving", 0.5 + alive(s).length * 0.05);
  practise(s, "trading", 0.15);
  const keeper = theKeeper(s);
  if (keeper) push(`${keeper.name} did this week's report. You're reading it because she allows you to.`, "warning", 11, keeper.id);
  refreshPlayer(s);

  const report: WeekReport = {
    week,
    ledger: led.lines,
    lines: lines.sort((a, b) => b.weight - a.weight),
    cash_start: cashStart,
    cash_end: arc.cash,
    rep_start: repStart,
    rep_end: arc.rep,
    problems,
    city: cityThisWeek(s),
  };
  s.reports.push(report);
  if (s.reports.length > 24) s.reports.shift();
  return report;
}

/** Roughly how much sex a week of this assignment is. Feeds conception, and nothing else — the
 *  income model already counts customers separately. */
function sexualExposure(p: Person, s: SaveState): number {
  // The two jobs that are only you: nothing to conceive from if you can't sire.
  if ((p.assignment === "please you" || p.assignment === "be your Concubine") && !canSire(s)) return 0;
  switch (p.assignment) {
    case "work in the brothel": return 5;
    case "be confined in the arcade": return 6;
    case "whore": return 4;
    case "public servant": return 4;
    case "fucktoy": return 4;
    case "please you": return 3;
    case "serve in the club": return 2;
    case "be your Concubine": return 3;
    default: return 0;
  }
}

function weekMemory(p: Person, where: string, money: { customers: number; note: string }): string {
  if (money.customers > 60) return `${money.customers} customers in ${where}`;
  if (money.customers > 0) return `${money.customers} customers in ${where}`;
  if (p.assignment === "rest" || p.assignment === "rest in the spa") return `a week of rest in ${where}`;
  return `a week working in ${where}`;
}

function applyProjectEffect(s: SaveState, effect: { effect: string; payload?: Record<string, unknown> }): void {
  const arc = s.arcology;
  switch (effect.effect) {
    case "facility_level": {
      const id = String(effect.payload?.facility ?? "");
      const f = arc.facilities[id];
      if (f) { f.level++; f.capacity += Number(effect.payload?.capacity ?? 4); }
      break;
    }
    case "security": arc.security = clamp(arc.security + Number(effect.payload?.amount ?? 10), 0, 100); break;
    case "prosperity": arc.prosperity = clamp(arc.prosperity + Number(effect.payload?.amount ?? 5), 0, 200); break;
    case "doctrine_research": {
      const id = String(effect.payload?.doctrine ?? "");
      if (arc.doctrines[id]) arc.doctrines[id].research = true;
      break;
    }
  }
}
