/**
 * SAVE STATE — creation, repair, and the guarantees the rest of the engine relies on.
 *
 * `sanitize` is the load path for every save, including ones written by this build five minutes
 * ago. It exists because a save is a document that outlives the code that wrote it: a field added
 * this week is missing from every save made last week, and the alternative to filling it in here
 * is a crash somewhere far away with no clue in it. Everything it fills is a default that a
 * running game would have produced anyway.
 */
import { seedOwnLife } from "./ownlife";
import { seedCharacter } from "./character";
import { repairCuckold } from "./cuckold";
import { compactMemory, similar } from "./memory";
import { hasWomb } from "./pregnancy";
import { reconcileAnatomy } from "./genitals";
import { assWord } from "./generate";
import { sane, settleOldSurgery } from "./health";
import { feetOf } from "./genitals";
import { newWorld } from "./world";
import type { Arcology, Facility, Person, Pronouns, SaveState, Sector, StandingOrder } from "./types";
import { SCHEMA_VERSION, DEFAULT_MODELS } from "./types";
import { FACILITIES } from "../data/facilities";
import { generatePerson } from "./generate";
import { newMemory } from "./memory";
import { refresh } from "./obedience";
import { newPsyche } from "./psyche";
import { defaultOrders } from "./rules";
import { rollMarkets } from "./market";
import { rng } from "./rng";
import { newStory } from "./story";
import { newRun } from "./run";
import { ORIGIN_BY_ID } from "../data/story";
import { settleBody, settlePronouns, type Kit } from "./you";
import { forgetOwnerAsStranger } from "./saga";
import { allowanceFromMemory } from "./allowance";
import { settleFaces } from "./faceid";
import { claimSpeech } from "./voice";
import { unsoften } from "./soft";
import { soundsLikeAnalysis } from "./style";
import { cityOf, cityYield } from "./city";

export interface NewGameOptions {
  arcology_name?: string;
  player_name?: string;
  player_career?: string;
  starting_slaves?: number;
  starting_cash?: number;
  difficulty?: "generous" | "standard" | "hard";
  seed?: string;
  /** Who you were before the building. See data/story/origins.ts. */
  origin?: string;
  /** What the household calls you. */
  address?: string;
  /** Run the Supplicationism chain as well. */
  supplication?: boolean;
  /** The main plot; on unless turned off at the start. */
  plot?: boolean;
  /** Up to two twists on the world. See engine/run.ts. */
  twists?: string[];
  /** What you have between your legs, which the scenes follow. The rest is shaped on the You screen. */
  kit?: Kit;
  pronouns?: Pronouns;
}

const ARC_NAMES = ["Aurelia", "Vireo", "Marrow", "Halcyon", "Sable Rock", "Ninth Terrace", "Corvid", "The Spindle", "Tessellate", "Antioch"];

export function newGame(opts: NewGameOptions = {}): SaveState {
  const seed = opts.seed ?? String(Math.floor(Math.random() * 1e9));
  const r = rng(`newgame:${seed}`);
  const difficulty = opts.difficulty ?? "standard";
  const cash = opts.starting_cash ?? (difficulty === "generous" ? 120000 : difficulty === "hard" ? 30000 : 65000);

  const sectors: Sector[] = [];
  for (let i = 0; i < 24; i++) {
    sectors.push({
      id: `s${i}`,
      kind: i < 12 ? "residential" : i < 18 ? "commercial" : i < 22 ? "industrial" : "civic",
      owner: i < 4 ? "you" : r.chance(0.5) ? "citizen" : "vacant",
      condition: Math.round(r.normal(60, 15)),
    });
  }

  // Facilities all exist as records at level 0 — "not built" is a state a building can be in, and
  // making it one saves every consumer from asking whether the key is there.
  const facilities: Record<string, Facility> = {};
  for (const def of FACILITIES) {
    facilities[def.id] = {
      id: def.id, kind: def.id, name: def.name, level: 0, upgrades: {},
      capacity: 0, workers: [], decoration: 0, settings: {},
    };
  }
  // You start with somewhere to put people and somewhere to sleep.
  facilities["servants"].level = 1;
  facilities["servants"].capacity = 8;
  facilities["master_suite"].level = 1;
  facilities["master_suite"].capacity = 4;

  const arcology: Arcology = {
    name: opts.arcology_name ?? r.pick(ARC_NAMES),
    region: r.pick(["the Gulf", "the South China Sea", "the Baltic approaches", "the Sahel coast", "the Australian bight"]),
    week: 1,
    cash,
    rep: 200,
    prosperity: 55,
    security: 45,
    crime: 25,
    population: 1200,
    ownership: 18,
    sectors,
    facilities,
    doctrines: {},
    policies: {},
    neighbours: [
      { id: "n-e", name: "Kestrel", direction: "east", prosperity: 62, ownership: 0, attitude: 5, doctrines: [] },
      { id: "n-n", name: "Ardent", direction: "north", prosperity: 48, ownership: 0, attitude: -12, doctrines: [] },
      { id: "n-w", name: "Cinder", direction: "west", prosperity: 80, ownership: 0, attitude: -35, doctrines: [] },
    ],
    loans: [],
    projects: [],
    mercenaries: { hired: false, strength: 0, loyalty: 0, upkeep: 0 },
    food: { stores: 900, production: 0, consumption: 0 },
    public_standing: 0,
  };

  const people: Record<string, Person> = {};
  const memory: Record<string, ReturnType<typeof newMemory>> = {};
  const count = opts.starting_slaves ?? 3;
  for (let i = 0; i < count; i++) {
    const p = generatePerson({ seed: `${seed}:start:${i}`, week: 1, central: true });
    p.economics.price_paid = 0;
    p.origin.acquired_how = "came with the arcology";
    people[p.id] = p;
    memory[p.id] = newMemory();
    refresh(p, memory[p.id]);
  }

  const state: SaveState = {
    id: `warp-${Date.now().toString(36)}`,
    name: `${arcology.name}, week 1`,
    schema: SCHEMA_VERSION,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    models: { ...DEFAULT_MODELS },
    arcology,
    people,
    memory,
    edges: [],
    rumors: [],
    player: {
      name: opts.player_name ?? "you",
      pronouns: opts.pronouns ?? "they/them",
      pronouns_set: !!opts.pronouns,
      age: 34,
      title: "owner",
      body: { appearance_facts: "ordinary-looking, in expensive but plain clothes" },
      career: opts.player_career ?? "trader",
      skills: { trading: 35, hacking: 15, slaving: 25, engineering: 15, medicine: 10, command: 10, diplomacy: 15 },
      household_read: { feared: 0, trusted: 0, label: "nobody in particular" },
    },
    scene: {
      location: "the penthouse",
      time: "Week 1, Monday 09:00",
      present: Object.keys(people).slice(0, 2),
      present_prev: [],
      weather: "hot",
      arrivals_pending: [],
      departures_pending: [],
    },
    turn: 0,
    history: [],
    reports: [],
    orders: defaultOrders(),
    events: [],
    notifications: [],
    market: { week: 1, offers: {}, orders: [] },
    retcons: [],
    canon: [
      `${arcology.name} is a Free City arcology in ${arcology.region}. Slavery is legal here.`,
      "You own a controlling share of it.",
    ],
    integrity: { fires: [] },
    snapshots: [],
    telemetry: [],
    corrections: {},
  };

  // Who you were, and the story that comes with it. Setup runs before the story so an origin's
  // household changes are in place when its arc picks who it is about.
  if (opts.address) state.player.address = opts.address;
  if (opts.kit) settleBody(state, opts.kit);
  settlePronouns(state);
  const origin = ORIGIN_BY_ID[opts.origin ?? ""];
  if (origin) {
    origin.setup(state, r);
    if (difficulty === "generous") state.arcology.cash += 50000;
    if (difficulty === "hard") state.arcology.cash = Math.round(state.arcology.cash * 0.55);
  }
  newRun(state, seed, opts.twists ?? []);
  newStory(state, origin?.id ?? "none", seed, opts.supplication ?? false, opts.plot ?? true);
  for (const p of Object.values(state.people)) refresh(p, state.memory[p.id]);
  // The city starts with its people housed. It used to start 1,200 against room for 400 and spend
  // the first months emptying out.
  cityOf(state);
  state.arcology.population = Math.min(state.arcology.population, Math.round((400 + cityYield(state).housing) * 0.9));

  state.market = rollMarkets(state);
  return state;
}

/** Load-path repair. Idempotent, cheap, and the only place defaults are invented. */
export function sanitize(raw: SaveState): SaveState {
  const s = raw;
  s.schema = s.schema ?? SCHEMA_VERSION;
  s.models = { ...DEFAULT_MODELS, ...(s.models ?? {}) };
  s.people = s.people ?? {};
  s.memory = s.memory ?? {};
  // The owner was "they" for everyone before there was a choice; settle it from body and address.
  if (s.player) { settlePronouns(s); forgetOwnerAsStranger(s); }
  // Old saves filed the same beat week after week; fold the repeats together once, on load.
  for (const m of Object.values(s.memory)) if (m?.episodic) compactMemory(m);
  // Rumors that say the same thing are one rumor.
  if (Array.isArray(s.rumors)) s.rumors = s.rumors.filter((r, i, all) => !all.slice(0, i).some((o) => similar(o.content, r.content)));
  if (Array.isArray(s.canon)) s.canon = s.canon.filter((c, i, all) => !all.slice(0, i).some((o) => similar(o, c)));
  // Facts from walks used to go into canon, so one place followed you everywhere. They live on
  // their deed now; take them back out.
  if (Array.isArray(s.canon) && Array.isArray(s.deeds)) {
    const walkFacts = s.deeds.filter((d) => d.source === "walk" && d.fact).map((d) => d.fact as string);
    if (walkFacts.length) s.canon = s.canon.filter((c) => !walkFacts.includes(c));
    // Rumours that retell a walk are local gossip: tag them with the place (or "a walk" when the
    // save predates places), so they stop turning up everywhere.
    const walks = s.deeds.filter((d) => d.source === "walk");
    for (const r of s.rumors ?? []) if (!r.where) { const d = walks.find((w) => similar(w.summary.replace(/^You /, "the owner "), r.content)); if (d) r.where = d.where ?? "walk"; }
  }
  for (const p of Object.values(s.people)) if (p.status === "owned" || p.status === "indentured") allowanceFromMemory(s, p);
  for (const p of Object.values(s.people)) { claimSpeech(p); unsoften(s, p); }
  // Records written as analysis ("neither of them pretends…") taught every later scene to talk like
  // that. Old saves have some; they go.
  for (const p of Object.values(s.people)) if (p.ways) p.ways = p.ways.filter((w) => !soundsLikeAnalysis(w.text));
  for (const d of s.deeds ?? []) if (d.fact && soundsLikeAnalysis(d.fact)) delete d.fact;
  // One person, one record: ids for everyone met, and duplicate spellings folded together.
  settleFaces(s);
  s.edges = s.edges ?? [];
  s.rumors = s.rumors ?? [];
  s.history = s.history ?? [];
  s.reports = s.reports ?? [];
  s.orders = (s.orders ?? []) as StandingOrder[];
  s.events = s.events ?? [];
  s.notifications = s.notifications ?? [];
  s.retcons = s.retcons ?? [];
  s.canon = s.canon ?? [];
  s.integrity = s.integrity ?? { fires: [] };
  s.snapshots = s.snapshots ?? [];
  s.telemetry = s.telemetry ?? [];
  s.corrections = s.corrections ?? {};
  s.market = s.market ?? { week: s.arcology?.week ?? 1, offers: {}, orders: [] };

  if (s.arcology) {
    s.arcology.projects = s.arcology.projects ?? [];
    s.arcology.loans = s.arcology.loans ?? [];
    s.arcology.doctrines = s.arcology.doctrines ?? {};
    s.arcology.policies = s.arcology.policies ?? {};
    s.arcology.food = s.arcology.food ?? { stores: 500, production: 0, consumption: 0 };
    s.arcology.mercenaries = s.arcology.mercenaries ?? { hired: false, strength: 0, loyalty: 0, upkeep: 0 };
    for (const def of FACILITIES) {
      if (!s.arcology.facilities[def.id]) {
        s.arcology.facilities[def.id] = { id: def.id, kind: def.id, name: def.name, level: 0, upgrades: {}, capacity: 0, workers: [], decoration: 0, settings: {} };
      }
    }
    // Saves from before the world existed get one, starting from today.
    if (!s.world) s.world = newWorld(s);
  }

  for (const p of Object.values(s.people)) {
    p.psyche = p.psyche ?? newPsyche(0);
    p.psyche.active_states = p.psyche.active_states ?? [];
    p.psyche.state_ages = p.psyche.state_ages ?? {};
    p.counters = p.counters ?? {};
    p.rules_applied = p.rules_applied ?? [];
    p.body.marks = p.body.marks ?? [];
    // Saves from before genital detail: the sack starts fitted, and feet are derived from the body.
    if (p.body.scrotum === undefined) p.body.scrotum = p.body.balls ?? 0;
    feetOf(p);
    reconcileAnatomy(p);
    if (p.body.appearance_facts && !/\bass\b/.test(p.body.appearance_facts)) p.body.appearance_facts = p.body.appearance_facts.replace(/\.\s*$/, `, ${assWord(p.body.butt)}.`);
    p.health.injuries = p.health.injuries ?? [];
    p.health.drugs = p.health.drugs ?? [];
    // A missing or broken recovery count (older saves) must not become NaN and never count down.
    p.health.recovery_weeks = sane(p.health.recovery_weeks);
    p.womb.fetuses = p.womb.fetuses ?? [];
    // Nobody carries without a womb. Older saves could have got a cock-only slave pregnant.
    if (!hasWomb(p) && p.womb.fetuses.length) { p.womb.fetuses = []; p.womb.weeks = 0; }
    p.womb.sired_by = p.womb.sired_by ?? {};
    p.skills.management = p.skills.management ?? {};
    p.persona.fetishes = p.persona.fetishes ?? [];
    p.persona.texture = p.persona.texture ?? [];
    seedCharacter(p, undefined, false);
    // Spoiling didn't exist before: read it off what she's been given and how long since she was disciplined.
    if (p.bond.indulged === undefined) p.bond.indulged = Math.min(70, (p.room?.extras?.length ?? 0) * 4 + (p.bond.weeks_since_cruelty >= 6 ? 10 : 0));
    seedOwnLife(p);
    if (!s.memory[p.id]) s.memory[p.id] = newMemory();
    s.memory[p.id].facts = s.memory[p.id].facts ?? [];
    settleOldSurgery(s, p);
    // Facility membership: the facility is authoritative, so a person pointing at a facility that
    // does not hold them is corrected rather than trusted.
    if (p.facility && !s.arcology?.facilities[p.facility]?.workers.includes(p.id)) {
      const f = s.arcology?.facilities[p.facility];
      if (f && f.level > 0 && f.workers.length < f.capacity) f.workers.push(p.id);
      else p.facility = undefined;
    }
    refresh(p, s.memory[p.id]);
  }
  // A save from before the story existed keeps the plot chain it was playing and joins the deck
  // from here, with no origin arc — it already has a history.
  if (!s.story && s.arcology) newStory(s, "none", s.id, true, s.arcology.week < 6);
  if (!s.run && s.arcology) newRun(s, s.id, []);
  // A story with another man from before every word of it was the model's.
  repairCuckold(s);

  // A save written before the return rule existed has the old three orders and a household that
  // may already be parked in the spa with no way out. Add the missing one rather than resetting
  // orders wholesale, which would throw away everything the player has written.
  if (s.orders && !s.orders.some((o) => o.id === "o-return")) {
    const fresh = defaultOrders().find((o) => o.id === "o-return");
    if (fresh) s.orders.push(fresh);
  }
  return s;
}

/** ROLLBACK RING. One week or one scene turn back, cheaply, without an export. */
export function snapshot(s: SaveState): void {
  const blob = JSON.stringify({ ...s, snapshots: [] });
  s.snapshots.push({ turn: s.turn, week: s.arcology.week, blob });
  while (s.snapshots.length > 8) s.snapshots.shift();
}

export function rollback(s: SaveState): SaveState | null {
  const snap = s.snapshots.pop();
  if (!snap) return null;
  const restored = sanitize(JSON.parse(snap.blob) as SaveState);
  restored.snapshots = s.snapshots;
  return restored;
}
